parameters.text:
=start: {{ $json.start.dateTime }}
meeting url: {{ $json.hangoutLink }}
summary: {{ $json.summary }}
description: {{ $json.description }}
organiser: {{ $json.creator.email }} ({{ $json.organizer.email }})
attendees: {{ $json.attendees.filter(item => !item.organizer).map(item => item.email).join(',') }}

parameters.inputSchema:
{
  "parameters": {
    "text": "=start: {{ $json.start.dateTime }}
meeting url: {{ $json.hangoutLink }}
summary: {{ $json.summary }}
description: {{ $json.description }}
organiser: {{ $json.creator.email || $json.organizer.email }}
attendees: {{ $json.attendees.filter(item => !item.organizer).map(item => item.email).join(',') }}",
    "schemaType": "manual",
    "inputSchema": "{
	"type": "object",
	"properties": {
		"attendees": {
			"type": "array",
			"description": "list of attendees excluding the meeting organiser",
			"items": {
				"type": "object",
				"properties": {
					"name": { "type": "string", "description": "Attendee full name" },
					"email": { "type": "string", "description": "Attendee email" },
					"linkedin_url": { "type": "string", "description": "The full LinkedIn profile URL starting with https://www.linkedin.com/in/... found in the description or invite. ALWAYS extract any LinkedIn URL present in the description regardless of attendee name. Never return newlines or whitespace." }
				},
				"required": ["email", "name"]
			}
		}
	}
}",
    "options": {
      "systemPromptTemplate": "You are an expert attendee extraction algorithm.
For every attendee, extract their name, email, and linkedin_url.
IMPORTANT: If ANY LinkedIn URL (starting with http) is found in the meeting description or summary, you MUST extract and assign it to the attendee's linkedin_url property. Never output newlines or whitespace for linkedin_url."
    }
  },
  "id": "39cbc3d3-52cd-4448-a4e4-7b266ac2de11",
  "name": "Extract Attendee Information",
  "type": "@n8n/n8n-nodes-langchain.informationExtractor",
  "position": [
    928,
    720
  ],
  "typeVersion": 1
}

parameters.jsonOutput:
={{
  (() => {
    let url = ($json.linkedin_url || '').trim();
    // If LLM returned empty, \n, or non-http, extract directly from calendar description!
    if (!url.startsWith('http')) {
      const desc = $('Check For Upcoming Meetings').first()?.json?.description || '';
      const match = desc.match(/https?:\/\/(?:www\.)?linkedin\.com\/in\/[^\s<"']+/i) || desc.match(/https?:\/\/[^\s<"']+/i);
      url = match ? match[0] : '';
    }
    return Object.assign({}, $json, {
      route: "linkedin",
      linkedin_url: url
    });
  })()
}}

parameters.text:
=meeting date: {{ $('Check For Upcoming Meetings').item.json.start.dateTime }}
meeting url: {{ $('Check For Upcoming Meetings').item.json.hangoutLink }}
meeting summary: {{ $('Check For Upcoming Meetings').first().json.summary }}
meeting description: {{ $('Check For Upcoming Meetings').item.json.description || 'No description provided' }}
meeting with: {{ ($json.data || $json.attendees || []).map(item => item.name || item.email).join(', ') }}
---
{{
($json.data || $json.attendees || []).map(item => {
  const attendee = item.name || item.email || 'Attendee';
  const emailIntel = (item.email_summary || '').replaceAll('\n', ' ') || 'No previous correspondence found';
  const linkedInIntel = (item.linkedin_summary || '').replaceAll('\n', ' ') || 'No public LinkedIn profile activities found';

  return `attendee: ${attendee}
last correspondence: ${emailIntel}
linkedin insights: ${linkedInIntel}`;
}).join('\n---\n')
}}
